function getYawForPewFacingTarget(x: number, z: number, targetX: number, targetZ: number) {
  return Math.atan2(-(targetX - x), -(targetZ - z));
}

function getAvatarYawFacingTarget(x: number, z: number, targetX: number, targetZ: number) {
  return Math.atan2(targetX - x, -(targetZ - z));
}

